from pathlib import Path
import ast

ROOT=Path.cwd()
SUB=ROOT/"qseries_v2"/"oracle_execution"
SUB.mkdir(parents=True,exist_ok=True)

MOD=SUB/"oracle_032_executable_wealth_simulation_accounting.py"
TEST=ROOT/"test_oracle_032_executable_wealth_simulation_accounting.py"
RUN=ROOT/"run_oracle_032_executable_wealth_simulation_accounting.py"

MODULE_SOURCE='\nfrom __future__ import annotations\nfrom pathlib import Path\n\nfrom qseries_v2.oracle_execution import oracle_031_saved_alt_atomic_shadow_cutover as q31\nfrom qseries_v2.oracle_strategy_intelligence.solana_money import qsb059_gav_reverse_atomic as q59\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_execution_engineering import qarb_087_two_second_compaction_liquidity_repair as q87\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_execution_engineering import qarb_088_two_second_executable_profit_accounting as q88\n\nEXECUTION_AUTHORITY=False\nPAPER_ONLY=True\nREAL_MONEY_MOVED=False\nMAX_TX_BYTES=1232\n\ndef wealth_attempt_candidate_simulations(user,kp,route,blockhash):\n    x=q31.execution_route(route)\n    token=x.get("token")\n\n    # Legacy HOT_SIGNAL route can arrive without the exact ORACLE-028 token context.\n    # It is not execution authority and is intentionally excluded from wealth accounting.\n    if not token:\n        print("[ORACLE032_SKIP] reason=NO_EXACT_TOKEN_CONTEXT",flush=True)\n        return None,[{\n            "name":"LEGACY_NO_TOKEN_CONTEXT",\n            "compiled":False,\n            "error":"NO_EXACT_TOKEN_CONTEXT",\n            "profitable":False,\n        }]\n\n    x,before,after=q31.apply_saved_alt(Path.cwd(),x)\n\n    print("[ORACLE032_ALT] token=%s base_alts=%d saved_alts=%d"%(\n        str(token)[:12],len(before),len(after)\n    ),flush=True)\n\n    candidates=list(q87.repaired_candidates(x))\n    rows=[]\n\n    for candidate in candidates:\n        name=str(candidate.get("name",""))\n\n        if "PUMP_METEORA_ONLY" in name:\n            row={\n                "name":name,\n                "compiled":False,\n                "error":"LIVE_REJECT_HELPER_STRIPPED_PUMP_SHELL",\n                "profitable":False,\n            }\n            rows.append(row)\n            print("[ORACLE032_CANDIDATE] %s REJECT=%s"%(\n                name,row["error"]\n            ),flush=True)\n            continue\n\n        row=q88.executable_candidate(\n            user,\n            kp,\n            x,\n            candidate,\n            [list(x.get("base_alts") or [])],\n            blockhash,\n            token,\n        )\n        rows.append(row)\n\n        print(\n            "[ORACLE032_WEALTH_SIM] token=%s candidate=%s compiled=%s bytes=%s "\n            "err=%s gross=%s fee=%s net=%s bps=%s residual_token=%s profitable=%s"\n            % (\n                str(token)[:10],\n                name,\n                row.get("compiled"),\n                row.get("bytes"),\n                row.get("sim_err"),\n                row.get("gross_sim_pnl_lamports"),\n                row.get("estimated_fee_lamports"),\n                row.get("net_sim_pnl_lamports"),\n                row.get("net_sim_bps"),\n                row.get("residual_token_delta_raw"),\n                row.get("profitable_after_fee"),\n            ),\n            flush=True,\n        )\n\n        if (\n            row.get("compiled")\n            and int(row.get("bytes",MAX_TX_BYTES+1))<=MAX_TX_BYTES\n            and row.get("sim_err") is None\n            and row.get("profitable_after_fee")\n        ):\n            winner=dict(row)\n            winner["profitable"]=True\n            winner["sim_pnl_lamports"]=row.get("net_sim_pnl_lamports")\n            winner["sim_bps"]=row.get("net_sim_bps")\n            return winner,rows\n\n    return None,rows\n\ndef install():\n    q31.install()\n    q59.attempt_candidate_simulations=wealth_attempt_candidate_simulations\n    return True\n\ndef run(seconds=300.0):\n    install()\n    from qseries_v2.oracle_execution import oracle_029_full_exact_pair_coverage_cutover as q29\n\n    print("[ORACLE-032] EXECUTABLE WEALTH SIMULATION ACCOUNTING",flush=True)\n    print("[PACKET] ORACLE-031 compact path preserved",flush=True)\n    print("[ACCOUNTING] QARB-088 native SOL + WSOL + WSOL rent",flush=True)\n    print("[FEE] getFeeForMessage measured separately",flush=True)\n    print("[RESIDUAL] intermediate token delta must equal zero",flush=True)\n    print("[LEGACY_HOT_SIGNAL] excluded without exact token context",flush=True)\n    print("[BROADCAST] disabled",flush=True)\n\n    return q29.run(seconds=seconds)\n\nif __name__=="__main__":\n    raise SystemExit(run())\n'
TEST_SOURCE='\nimport inspect, unittest\nfrom unittest.mock import patch\n\nfrom qseries_v2.oracle_execution import oracle_032_executable_wealth_simulation_accounting as q32\n\nclass T(unittest.TestCase):\n    def test_safety(self):\n        self.assertFalse(q32.EXECUTION_AUTHORITY)\n        self.assertTrue(q32.PAPER_ONLY)\n        self.assertFalse(q32.REAL_MONEY_MOVED)\n\n    def test_uses_q88_executable_accounting(self):\n        src=inspect.getsource(q32.wealth_attempt_candidate_simulations)\n        self.assertIn("q88.executable_candidate",src)\n        self.assertIn("net_sim_pnl_lamports",src)\n        self.assertIn("residual_token_delta_raw",src)\n\n    def test_no_mriya_lookup(self):\n        src=inspect.getsource(q32)\n        self.assertNotIn("recent_mriya_alt_keys",src)\n\n    def test_legacy_no_token_context_is_rejected(self):\n        winner,rows=q32.wealth_attempt_candidate_simulations(\n            "U",None,\n            {\n                "start_lamports":1000,\n                "pre_sim_net_lamports":1,\n                "pre_sim_bps":10.0,\n                "alts":[],\n                "candidates":[],\n            },\n            "BH",\n        )\n        self.assertIsNone(winner)\n        self.assertEqual(rows[0]["error"],"NO_EXACT_TOKEN_CONTEXT")\n\n    def test_profitable_requires_fee_and_zero_residual(self):\n        route={\n            "token":"T",\n            "start_lamports":1000,\n            "pre_sim_net_lamports":10,\n            "pre_sim_bps":100.0,\n            "alts":[],\n            "candidates":[("FULL",[])],\n        }\n        candidate={"name":"FULL","instructions":[],"pump_optional_removed":0}\n        measured={\n            "name":"FULL",\n            "compiled":True,\n            "bytes":1200,\n            "sim_err":None,\n            "gross_sim_pnl_lamports":20,\n            "estimated_fee_lamports":5,\n            "net_sim_pnl_lamports":15,\n            "net_sim_bps":150.0,\n            "residual_token_delta_raw":0,\n            "profitable_after_fee":True,\n        }\n        with patch.object(q32.q31,"apply_saved_alt",lambda root,r:(r,[],[])), \\\n             patch.object(q32.q87,"repaired_candidates",lambda r:[candidate]), \\\n             patch.object(q32.q88,"executable_candidate",lambda *a,**k:dict(measured)):\n            winner,rows=q32.wealth_attempt_candidate_simulations("U",None,route,"BH")\n        self.assertTrue(winner["profitable"])\n        self.assertEqual(winner["sim_pnl_lamports"],15)\n        self.assertEqual(winner["sim_bps"],150.0)\n\n    def test_no_broadcast(self):\n        self.assertNotIn("sendTransaction(",inspect.getsource(q32))\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n'
RUN_SOURCE='\nimport argparse\nfrom qseries_v2.oracle_execution.oracle_032_executable_wealth_simulation_accounting import run\n\nif __name__=="__main__":\n    p=argparse.ArgumentParser()\n    p.add_argument("--seconds",type=float,default=300.0)\n    a=p.parse_args()\n    raise SystemExit(run(seconds=a.seconds))\n'

ast.parse(MODULE_SOURCE)
ast.parse(TEST_SOURCE)
ast.parse(RUN_SOURCE)

MOD.write_text(MODULE_SOURCE.lstrip(),encoding="utf-8")
TEST.write_text(TEST_SOURCE.lstrip(),encoding="utf-8")
RUN.write_text(RUN_SOURCE.lstrip(),encoding="utf-8")

print("[PASS] ORACLE-032 executable wealth simulation accounting installed")
print("[PACKET] ORACLE-031 compact <=1232-byte path preserved")
print("[ACCOUNTING] QARB-088 native SOL + WSOL + rent + fee + token residual")
print("[HOT_PATH] Mriya lookup disabled")
print("[BROADCAST] disabled")
